{"ops":[
  {"src":1,"evid":"user: hey, I'm a freelance translator and I'm stuck on an Arabic term. translating a heritage-conservation report from Arabic into English for the Tazkira Heritage Trust and the phrase 'waqf ahli' keeps tripping me. is 'family endowment' ok or is there a better term?","op":"add","ent":"user","type":"user","attr":"role","val":"translator","kind":"fact","keep":"long","basis":"stated","conf":"high","sens":"none"},
