  {"src":4,"evid":"assistant: Waqf it is, glossed once. A quick review checklist helps with a junior's draft: terminology consistency, numbers and dates, name transliteration, then register. Reviewing in that order keeps your feedback focused.","op":"update","ref":"m398","ent":"Yuki","attr":"role","val":"on-call swap","kind":"fact","keep":"long","why":"changed","basis":"stated","conf":"medium","sens":"none"}
]}

